INSERT INTO companies (name, slug, description, owner_id, is_verified, location, industry, company_size, website, founded_year) VALUES
('Vodafone Albania', 'vodafone-albania', 'Leading telecommunications provider in Albania, offering mobile, internet, and digital services to millions of customers across the country.', '2ae25656-f7bd-499f-a945-71f8fb277710', true, 'Tiranë', 'Telecommunications', '1000+', 'https://www.vodafone.al', 2001),
('BKT - Banka Kombëtare Tregtare', 'bkt-bank', 'The largest and oldest bank in Albania, providing comprehensive banking and financial services including retail, corporate, and investment banking.', '2ae25656-f7bd-499f-a945-71f8fb277710', true, 'Tiranë', 'Finance & Banking', '500-1000', 'https://www.bkt.com.al', 1925),
('Balfin Group', 'balfin-group', 'One of the most significant investment groups in Albania and the Western Balkans, with diverse interests in real estate, mining, banking, and retail.', '2ae25656-f7bd-499f-a945-71f8fb277710', true, 'Tiranë', 'Investments & Real Estate', '1000+', 'https://www.balfin.al', 2007),
('Conad Albania', 'conad-albania', 'Major retail supermarket chain operating across Albania, providing quality food products and household goods at competitive prices.', '2ae25656-f7bd-499f-a945-71f8fb277710', true, 'Tiranë', 'Retail & FMCG', '500-1000', 'https://www.conad.al', 2006),
('Ikub.al', 'ikub-al', 'Albania''s leading digital media and technology company, specializing in online news, digital advertising, and software development solutions.', '2ae25656-f7bd-499f-a945-71f8fb277710', true, 'Tiranë', 'Technology & Media', '50-200', 'https://www.ikub.al', 2005);
INSERT INTO jobs (title, slug, description, requirements, location, company_id, posted_by, category, job_type, experience_level, is_active, salary_min, salary_max, salary_currency, skills) VALUES
('Senior Network Engineer', 'senior-network-engineer-vodafone-' || extract(epoch from now())::bigint, '<h2>About the Role</h2><p>We''re looking for an experienced Network Engineer to design, implement, and maintain our telecommunications infrastructure across Albania. You''ll work with cutting-edge 5G technology and help shape the future of connectivity.</p><h3>What You''ll Do</h3><ul><li>Design and optimize network architecture for mobile and fixed-line services</li><li>Monitor network performance and troubleshoot complex issues</li><li>Lead 5G rollout projects across major Albanian cities</li><li>Collaborate with international teams on technology upgrades</li></ul>', '<ul><li>5+ years in telecom network engineering</li><li>CCNP or equivalent certification</li><li>Experience with 4G/5G technologies</li><li>Fluent in Albanian and English</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'vodafone-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'senior', true, 120000, 180000, 'ALL', ARRAY['Networking', 'Cisco', '5G', 'TCP/IP', 'Linux']),
('Digital Marketing Manager', 'digital-marketing-manager-vodafone-' || extract(epoch from now())::bigint, '<h2>Join Our Marketing Team</h2><p>Drive Vodafone Albania''s digital presence and help us connect with millions of customers through innovative campaigns. This is your chance to shape one of Albania''s most recognized brands.</p><h3>Responsibilities</h3><ul><li>Plan and execute digital marketing campaigns across all channels</li><li>Manage social media strategy and content calendar</li><li>Analyze campaign performance and optimize ROI</li><li>Lead a team of 4 digital marketing specialists</li></ul>', '<ul><li>3+ years in digital marketing, preferably in telecom</li><li>Experience with Google Ads, Meta Ads, and analytics tools</li><li>Strong analytical and creative skills</li><li>Bachelor''s degree in Marketing or related field</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'vodafone-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Marketing', 'full_time', 'mid', true, 90000, 130000, 'ALL', ARRAY['Digital Marketing', 'Google Ads', 'Social Media', 'Analytics', 'SEO']),
('Customer Experience Specialist', 'customer-experience-specialist-vodafone-' || extract(epoch from now())::bigint, '<h2>Make Every Customer Interaction Count</h2><p>At Vodafone, our customers come first. We need passionate people who can turn every touchpoint into a positive experience. If you love solving problems and making people smile, this role is for you.</p><h3>Your Day-to-Day</h3><ul><li>Handle customer inquiries via phone, email, and chat</li><li>Resolve technical issues and billing questions</li><li>Identify opportunities to improve customer satisfaction</li><li>Contribute to knowledge base and training materials</li></ul>', '<ul><li>1-2 years customer service experience</li><li>Excellent communication skills in Albanian</li><li>English proficiency is a plus</li><li>Patient, empathetic, and solution-oriented</li></ul>', 'Durrës', (SELECT id FROM companies WHERE slug = 'vodafone-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Customer Service', 'full_time', 'entry', true, 45000, 65000, 'ALL', ARRAY['Customer Service', 'Communication', 'Problem Solving', 'CRM']),
('Data Analyst', 'data-analyst-vodafone-' || extract(epoch from now())::bigint, '<h2>Turn Data Into Decisions</h2><p>Join our analytics team and help Vodafone Albania make smarter, data-driven decisions. You''ll work with massive datasets from millions of subscribers to uncover insights that drive business growth.</p><h3>What You''ll Work On</h3><ul><li>Analyze subscriber behavior and usage patterns</li><li>Build dashboards and automated reports for stakeholders</li><li>Develop predictive models for churn prevention</li><li>Support pricing and product teams with market analysis</li></ul>', '<ul><li>2+ years experience in data analysis</li><li>Proficiency in SQL, Python, and visualization tools (Tableau/Power BI)</li><li>Strong statistical knowledge</li><li>Telecom industry experience preferred</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'vodafone-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'mid', true, 80000, 120000, 'ALL', ARRAY['SQL', 'Python', 'Tableau', 'Data Analysis', 'Statistics']),
('HR Business Partner', 'hr-business-partner-vodafone-' || extract(epoch from now())::bigint, '<h2>Shape Our People Strategy</h2><p>We''re hiring an HR Business Partner to work closely with leadership and help build a workplace where people thrive. You''ll be the bridge between business strategy and talent development.</p><h3>Key Responsibilities</h3><ul><li>Partner with department heads on workforce planning</li><li>Drive talent acquisition and employer branding</li><li>Manage employee relations and performance processes</li><li>Lead diversity and inclusion initiatives</li></ul>', '<ul><li>4+ years HR experience in a corporate environment</li><li>Knowledge of Albanian labor law</li><li>SHRM or CIPD certification preferred</li><li>Excellent interpersonal and negotiation skills</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'vodafone-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Human Resources', 'full_time', 'senior', true, 100000, 150000, 'ALL', ARRAY['HR Management', 'Recruitment', 'Employee Relations', 'Labor Law']);
INSERT INTO jobs (title, slug, description, requirements, location, company_id, posted_by, category, job_type, experience_level, is_active, salary_min, salary_max, salary_currency, skills) VALUES
('Credit Risk Analyst', 'credit-risk-analyst-bkt-' || extract(epoch from now())::bigint, '<h2>Assess, Analyze, Protect</h2><p>BKT is looking for a sharp Credit Risk Analyst to evaluate lending risks and safeguard the bank''s portfolio. You''ll work at the intersection of finance and analytics, making decisions that matter.</p><h3>What You''ll Do</h3><ul><li>Evaluate credit applications for corporate and retail clients</li><li>Develop and maintain risk scoring models</li><li>Monitor portfolio quality and prepare risk reports</li><li>Ensure compliance with Bank of Albania regulations</li></ul>', '<ul><li>3+ years in credit risk or financial analysis</li><li>Strong knowledge of financial statements and ratios</li><li>Experience with risk modeling tools</li><li>CFA or FRM certification is a plus</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'bkt-bank'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'mid', true, 95000, 140000, 'ALL', ARRAY['Risk Analysis', 'Financial Modeling', 'Credit Assessment', 'Excel', 'Compliance']),
('Branch Manager - Vlorë', 'branch-manager-vlore-bkt-' || extract(epoch from now())::bigint, '<h2>Lead Our Vlorë Branch</h2><p>Take charge of one of our key coastal branches. As Branch Manager, you''ll drive business growth while ensuring exceptional banking service for our customers in the Vlorë region.</p><h3>Your Mission</h3><ul><li>Manage daily branch operations and a team of 15+ employees</li><li>Achieve sales targets for deposits, loans, and banking products</li><li>Build relationships with local businesses and community leaders</li><li>Ensure regulatory compliance and audit readiness</li></ul>', '<ul><li>5+ years banking experience with 2+ years in management</li><li>Proven track record in sales and team leadership</li><li>Knowledge of Albanian banking regulations</li><li>Bachelor''s in Finance, Economics, or Business</li></ul>', 'Vlorë', (SELECT id FROM companies WHERE slug = 'bkt-bank'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'senior', true, 130000, 180000, 'ALL', ARRAY['Banking', 'Team Leadership', 'Sales', 'Compliance', 'Customer Relations']),
('Software Developer - Core Banking', 'software-developer-core-banking-bkt-' || extract(epoch from now())::bigint, '<h2>Build the Future of Banking</h2><p>Help us modernize BKT''s core banking systems. You''ll develop applications that handle millions of transactions daily and serve customers across all our branches and digital channels.</p><h3>What You''ll Build</h3><ul><li>Develop and maintain core banking applications</li><li>Integrate with payment systems (SWIFT, SEPA, local clearing)</li><li>Build APIs for mobile and internet banking platforms</li><li>Participate in system architecture decisions</li></ul>', '<ul><li>3+ years Java or .NET development experience</li><li>Experience with banking or financial software</li><li>Knowledge of SQL databases and microservices</li><li>Understanding of banking security standards</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'bkt-bank'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'mid', true, 100000, 160000, 'ALL', ARRAY['Java', '.NET', 'SQL', 'REST APIs', 'Microservices']),
('Compliance Officer', 'compliance-officer-bkt-' || extract(epoch from now())::bigint, '<h2>Integrity Is Everything</h2><p>Join our compliance team and help BKT maintain the highest standards of regulatory compliance. You''ll play a crucial role in AML/KYC processes and ensure we meet all national and international obligations.</p><h3>Responsibilities</h3><ul><li>Monitor transactions for suspicious activity</li><li>Conduct KYC due diligence on high-risk clients</li><li>Prepare regulatory reports for the Bank of Albania</li><li>Train staff on compliance procedures and updates</li></ul>', '<ul><li>2+ years in banking compliance or audit</li><li>Knowledge of AML/CFT regulations</li><li>CAMS certification preferred</li><li>Detail-oriented with strong analytical skills</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'bkt-bank'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Legal', 'full_time', 'mid', true, 85000, 120000, 'ALL', ARRAY['AML', 'KYC', 'Compliance', 'Regulatory Reporting', 'Audit']),
('Teller / Customer Service Associate', 'teller-customer-service-bkt-' || extract(epoch from now())::bigint, '<h2>Start Your Banking Career</h2><p>Looking for your first step into banking? BKT offers a great environment to learn, grow, and build a career. As a Teller, you''ll be the face of BKT for our everyday customers.</p><h3>Day-to-Day Tasks</h3><ul><li>Process deposits, withdrawals, and transfers</li><li>Help customers with account inquiries and product information</li><li>Cross-sell banking products and services</li><li>Maintain accurate cash handling and daily balancing</li></ul>', '<ul><li>Bachelor''s degree (Finance or Economics preferred)</li><li>Strong numeracy and attention to detail</li><li>Friendly personality and service mindset</li><li>Basic computer skills</li></ul>', 'Shkodër', (SELECT id FROM companies WHERE slug = 'bkt-bank'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'entry', true, 40000, 55000, 'ALL', ARRAY['Customer Service', 'Cash Handling', 'Banking', 'Communication']);
INSERT INTO jobs (title, slug, description, requirements, location, company_id, posted_by, category, job_type, experience_level, is_active, salary_min, salary_max, salary_currency, skills) VALUES
('Real Estate Project Manager', 'real-estate-project-manager-balfin-' || extract(epoch from now())::bigint, '<h2>Build Landmark Projects</h2><p>Balfin Group is developing some of Albania''s most ambitious real estate projects. We need an experienced Project Manager to oversee construction and development from concept to completion.</p><h3>What You''ll Manage</h3><ul><li>Oversee residential and commercial development projects</li><li>Coordinate architects, contractors, and engineering teams</li><li>Manage budgets, timelines, and quality standards</li><li>Report progress to senior leadership and investors</li></ul>', '<ul><li>7+ years in construction or real estate project management</li><li>PMP certification preferred</li><li>Experience with large-scale developments</li><li>Strong leadership and negotiation skills</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'balfin-group'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Construction', 'full_time', 'senior', true, 150000, 220000, 'ALL', ARRAY['Project Management', 'Real Estate', 'Construction', 'Budgeting', 'AutoCAD']),
('Financial Controller', 'financial-controller-balfin-' || extract(epoch from now())::bigint, '<h2>Control the Numbers That Matter</h2><p>As Financial Controller, you''ll oversee financial reporting and internal controls across Balfin Group''s diverse portfolio of companies. This is a high-impact role for someone who loves complexity.</p><h3>Key Responsibilities</h3><ul><li>Prepare consolidated financial statements for the group</li><li>Design and enforce internal financial controls</li><li>Manage audits and tax compliance across subsidiaries</li><li>Provide financial analysis for strategic decisions</li></ul>', '<ul><li>5+ years in financial controlling or audit (Big 4 preferred)</li><li>CPA or ACCA qualification</li><li>Experience with IFRS and Albanian tax law</li><li>Advanced Excel and ERP system proficiency</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'balfin-group'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'senior', true, 140000, 200000, 'ALL', ARRAY['Financial Reporting', 'IFRS', 'Audit', 'ERP', 'Tax Compliance']),
('Investment Analyst', 'investment-analyst-balfin-' || extract(epoch from now())::bigint, '<h2>Find the Next Big Opportunity</h2><p>Help Balfin Group identify and evaluate investment opportunities across the Western Balkans. You''ll conduct market research, financial modeling, and due diligence for new ventures.</p><h3>What You''ll Do</h3><ul><li>Research and evaluate potential investment opportunities</li><li>Build financial models and valuation analyses</li><li>Conduct market research and competitive analysis</li><li>Prepare investment proposals and board presentations</li></ul>', '<ul><li>2-4 years in investment banking, private equity, or consulting</li><li>Strong financial modeling and valuation skills</li><li>MBA or CFA Level II+ preferred</li><li>Fluent in Albanian and English</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'balfin-group'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'mid', true, 100000, 160000, 'ALL', ARRAY['Financial Modeling', 'Valuation', 'Due Diligence', 'Market Research', 'Excel']),
('Legal Counsel', 'legal-counsel-balfin-' || extract(epoch from now())::bigint, '<h2>Protect Our Interests</h2><p>We need a skilled Legal Counsel to handle corporate and commercial legal matters across our diverse group of companies. You''ll advise on contracts, regulations, and corporate governance.</p><h3>Responsibilities</h3><ul><li>Draft and review commercial contracts and agreements</li><li>Advise on corporate governance and regulatory compliance</li><li>Handle real estate transactions and permits</li><li>Manage litigation and dispute resolution</li></ul>', '<ul><li>4+ years legal experience in corporate/commercial law</li><li>Bar admission in Albania</li><li>Experience in real estate or M&A transactions</li><li>Strong negotiation and drafting skills</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'balfin-group'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Legal', 'full_time', 'senior', true, 120000, 180000, 'ALL', ARRAY['Corporate Law', 'Contract Drafting', 'Real Estate Law', 'Compliance', 'M&A']),
('Marketing Communications Coordinator', 'marcom-coordinator-balfin-' || extract(epoch from now())::bigint, '<h2>Tell Our Story</h2><p>Help communicate Balfin Group''s vision and impact across Albania and the region. You''ll manage PR, events, and brand communications for one of the country''s most prominent business groups.</p><h3>Your Role</h3><ul><li>Coordinate PR activities and media relations</li><li>Organize corporate events and press conferences</li><li>Manage brand communications across group companies</li><li>Create content for corporate publications and social media</li></ul>', '<ul><li>2+ years in PR, communications, or marketing</li><li>Excellent writing skills in Albanian and English</li><li>Experience with event management</li><li>Creative thinker with attention to detail</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'balfin-group'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Marketing', 'full_time', 'mid', true, 70000, 100000, 'ALL', ARRAY['PR', 'Communications', 'Event Management', 'Content Writing', 'Social Media']);
INSERT INTO jobs (title, slug, description, requirements, location, company_id, posted_by, category, job_type, experience_level, is_active, salary_min, salary_max, salary_currency, skills) VALUES
('Store Manager - Elbasan', 'store-manager-elbasan-conad-' || extract(epoch from now())::bigint, '<h2>Run Your Own Store</h2><p>Take full ownership of our Elbasan supermarket. As Store Manager, you''ll lead a team of 30+ employees, drive sales, and ensure our customers always have a great shopping experience.</p><h3>What You''ll Manage</h3><ul><li>Daily store operations, staffing, and scheduling</li><li>Sales targets, promotions, and inventory management</li><li>Customer service standards and complaint resolution</li><li>Health, safety, and food hygiene compliance</li></ul>', '<ul><li>3+ years retail management experience</li><li>Strong leadership and people management skills</li><li>Knowledge of food safety regulations</li><li>Results-oriented with strong commercial awareness</li></ul>', 'Elbasan', (SELECT id FROM companies WHERE slug = 'conad-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Sales', 'full_time', 'mid', true, 80000, 110000, 'ALL', ARRAY['Retail Management', 'Team Leadership', 'Inventory Management', 'Sales', 'Food Safety']),
('Supply Chain Coordinator', 'supply-chain-coordinator-conad-' || extract(epoch from now())::bigint, '<h2>Keep the Shelves Full</h2><p>Our supply chain is the backbone of Conad Albania. We need a detail-oriented coordinator to ensure products flow smoothly from suppliers to our stores across the country.</p><h3>Key Tasks</h3><ul><li>Coordinate with suppliers and manage purchase orders</li><li>Optimize delivery routes and warehouse operations</li><li>Monitor stock levels and prevent out-of-stock situations</li><li>Negotiate terms with local and international suppliers</li></ul>', '<ul><li>2+ years in supply chain or logistics</li><li>Experience with ERP/inventory management systems</li><li>Strong organizational and analytical skills</li><li>Driver''s license required</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'conad-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Logistics', 'full_time', 'mid', true, 65000, 90000, 'ALL', ARRAY['Supply Chain', 'Logistics', 'Inventory Management', 'ERP', 'Procurement']),
('Quality Assurance Inspector', 'qa-inspector-conad-' || extract(epoch from now())::bigint, '<h2>Guarantee Quality on Every Shelf</h2><p>Help us maintain the highest food quality and safety standards across all Conad Albania stores. You''ll inspect products, audit processes, and ensure compliance with Albanian and EU regulations.</p><h3>Responsibilities</h3><ul><li>Inspect incoming products for quality and freshness</li><li>Audit store hygiene and food handling practices</li><li>Manage supplier quality assessments</li><li>Prepare reports for regulatory inspections</li></ul>', '<ul><li>Degree in Food Science, Chemistry, or related field</li><li>2+ years in food quality assurance</li><li>HACCP certification required</li><li>Willingness to travel between stores</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'conad-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Manufacturing', 'full_time', 'mid', true, 60000, 85000, 'ALL', ARRAY['Quality Assurance', 'HACCP', 'Food Safety', 'Auditing', 'Compliance']),
('Accountant', 'accountant-conad-' || extract(epoch from now())::bigint, '<h2>Numbers Tell a Story</h2><p>Join our finance team and help keep Conad Albania''s books accurate and compliant. You''ll handle accounts payable/receivable, VAT reporting, and monthly financial closings.</p><h3>Your Responsibilities</h3><ul><li>Process invoices and manage accounts payable/receivable</li><li>Prepare monthly VAT returns and tax declarations</li><li>Reconcile bank statements and general ledger accounts</li><li>Assist with annual financial audit preparation</li></ul>', '<ul><li>2+ years accounting experience</li><li>Knowledge of Albanian tax law and regulations</li><li>Proficiency in accounting software</li><li>Bachelor''s degree in Accounting or Finance</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'conad-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Finance', 'full_time', 'mid', true, 55000, 80000, 'ALL', ARRAY['Accounting', 'Tax Compliance', 'VAT', 'Excel', 'Financial Reporting']),
('Cashier (Part-Time)', 'cashier-part-time-conad-' || extract(epoch from now())::bigint, '<h2>Flexible Hours, Great Team</h2><p>Looking for a part-time role that fits around your schedule? Join Conad Albania as a cashier and be part of a friendly, supportive team. Perfect for students or anyone seeking flexible work.</p><h3>What You''ll Do</h3><ul><li>Operate POS systems and process customer payments</li><li>Assist customers with inquiries and product locations</li><li>Help with shelf stocking during quiet periods</li><li>Maintain a clean and organized checkout area</li></ul>', '<ul><li>No previous experience needed — we''ll train you!</li><li>Friendly and customer-focused attitude</li><li>Basic math skills</li><li>Available for shifts including weekends</li></ul>', 'Fier', (SELECT id FROM companies WHERE slug = 'conad-albania'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Customer Service', 'part_time', 'entry', true, 25000, 35000, 'ALL', ARRAY['Customer Service', 'POS Systems', 'Cash Handling']);
INSERT INTO jobs (title, slug, description, requirements, location, company_id, posted_by, category, job_type, experience_level, is_active, salary_min, salary_max, salary_currency, skills) VALUES
('Full Stack Developer', 'full-stack-developer-ikub-' || extract(epoch from now())::bigint, '<h2>Code That Reaches Millions</h2><p>Ikub.al''s platforms serve millions of Albanian users every month. We''re looking for a Full Stack Developer who can build fast, scalable web applications and isn''t afraid to tackle challenging problems.</p><h3>Tech Stack & Responsibilities</h3><ul><li>Build and maintain web applications using React and Node.js</li><li>Design and optimize PostgreSQL databases</li><li>Implement RESTful APIs and real-time features</li><li>Write clean, tested, and well-documented code</li></ul>', '<ul><li>3+ years full stack development experience</li><li>Proficiency in React, TypeScript, and Node.js</li><li>Experience with PostgreSQL and Redis</li><li>Understanding of CI/CD and cloud services (AWS/GCP)</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'ikub-al'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'mid', true, 90000, 140000, 'ALL', ARRAY['React', 'Node.js', 'TypeScript', 'PostgreSQL', 'AWS']),
('SEO & Content Strategist', 'seo-content-strategist-ikub-' || extract(epoch from now())::bigint, '<h2>Dominate Albanian Search</h2><p>Help Ikub.al maintain and grow its position as Albania''s most-visited digital platform. You''ll develop SEO strategies and content plans that drive organic traffic and engagement.</p><h3>What You''ll Own</h3><ul><li>Develop and execute SEO strategy across all Ikub properties</li><li>Conduct keyword research for Albanian and English content</li><li>Optimize existing content and create new SEO-driven articles</li><li>Monitor rankings, traffic, and competitor performance</li></ul>', '<ul><li>3+ years SEO experience with proven traffic growth results</li><li>Expertise in Google Search Console, Ahrefs, or SEMrush</li><li>Strong content writing skills in Albanian</li><li>Understanding of technical SEO and web performance</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'ikub-al'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Marketing', 'full_time', 'mid', true, 75000, 110000, 'ALL', ARRAY['SEO', 'Content Strategy', 'Google Analytics', 'Keyword Research', 'Content Writing']),
('UI/UX Designer', 'ui-ux-designer-ikub-' || extract(epoch from now())::bigint, '<h2>Design for Impact</h2><p>Shape the user experience of Albania''s most popular digital platforms. You''ll design intuitive interfaces that millions of people use daily — from news readers to job seekers.</p><h3>Your Design Work</h3><ul><li>Design user interfaces for web and mobile applications</li><li>Conduct user research and usability testing</li><li>Create wireframes, prototypes, and design systems</li><li>Collaborate closely with developers and product managers</li></ul>', '<ul><li>2+ years UI/UX design experience</li><li>Proficiency in Figma and prototyping tools</li><li>Portfolio demonstrating web/mobile design work</li><li>Understanding of accessibility and responsive design</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'ikub-al'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'mid', true, 70000, 100000, 'ALL', ARRAY['Figma', 'UI Design', 'UX Research', 'Prototyping', 'Design Systems']),
('Junior Content Writer (Albanian)', 'junior-content-writer-ikub-' || extract(epoch from now())::bigint, '<h2>Write for Albania''s Biggest Audience</h2><p>Got a way with words? Start your journalism career at Ikub.al, where your articles will be read by thousands of Albanians every day. We''ll mentor you and help you grow as a writer.</p><h3>What You''ll Write</h3><ul><li>Write news articles, features, and opinion pieces in Albanian</li><li>Cover topics including business, technology, and lifestyle</li><li>Research stories and verify facts before publishing</li><li>Optimize articles for SEO and social sharing</li></ul>', '<ul><li>Bachelor''s in Journalism, Communication, or Albanian Language</li><li>Excellent Albanian writing skills</li><li>Basic understanding of digital media and SEO</li><li>Curious mind and strong work ethic</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'ikub-al'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Marketing', 'full_time', 'entry', true, 40000, 60000, 'ALL', ARRAY['Content Writing', 'Albanian Language', 'SEO', 'Research', 'Social Media']),
('DevOps Engineer', 'devops-engineer-ikub-' || extract(epoch from now())::bigint, '<h2>Keep Everything Running Smoothly</h2><p>Our platforms need to be fast, secure, and always available. As DevOps Engineer, you''ll manage our infrastructure, automate deployments, and ensure our systems can handle traffic spikes.</p><h3>Infrastructure & Automation</h3><ul><li>Manage cloud infrastructure on AWS</li><li>Build and maintain CI/CD pipelines</li><li>Monitor system performance and respond to incidents</li><li>Implement security best practices and backups</li></ul>', '<ul><li>3+ years DevOps or systems engineering experience</li><li>Strong Linux administration skills</li><li>Experience with Docker, Kubernetes, and Terraform</li><li>Knowledge of monitoring tools (Prometheus, Grafana)</li></ul>', 'Tiranë', (SELECT id FROM companies WHERE slug = 'ikub-al'), '2ae25656-f7bd-499f-a945-71f8fb277710', 'Technology', 'full_time', 'mid', true, 95000, 150000, 'ALL', ARRAY['AWS', 'Docker', 'Kubernetes', 'CI/CD', 'Linux']);
